<template>
  <div class="rc" @mouseenter="hovered = true" @mouseleave="hovered = false">
    <!-- Image -->
    <div class="rc__img-wrap" @click="openDetails">
      <v-img
        :src="previewSrc"
        cover
        height="100%"
        @error="onPreviewError"
      >
        <template #placeholder>
          <div class="rc__img-placeholder">
            <v-progress-circular indeterminate color="white" size="24" />
          </div>
        </template>
      </v-img>

      <!-- Overlay hover -->
      <div class="rc__overlay" :class="{ 'rc__overlay--visible': hovered }">
        <button class="rc__overlay-btn" @click.stop="openDetails">
          <v-icon size="14">mdi-eye</v-icon>
          Voir
        </button>
      </div>

      <!-- Étoile favori -->
      <button
        class="rc__fav"
        :class="{ 'rc__fav--active': item.favorite }"
        @click.stop="toggleFavorite"
        :aria-label="item.favorite ? 'Retirer des favoris' : 'Ajouter aux favoris'"
      >
        <v-icon size="16">{{ item.favorite ? 'mdi-star' : 'mdi-star-outline' }}</v-icon>
      </button>
    </div>

    <!-- Corps -->
    <div class="rc__body">
      <p class="rc__title">{{ item.title || 'Sans titre' }}</p>
      <div class="rc__meta">
        <span v-if="item.totals?.kcal" class="rc__meta-item">
          <v-icon size="12">mdi-fire</v-icon>
          {{ Math.round(item.totals.kcal) }} kcal
        </span>
        <span v-if="item.servings" class="rc__meta-item">
          <v-icon size="12">mdi-silverware-fork-knife</v-icon>
          {{ item.servings }} portions
        </span>
      </div>
      <div v-if="item.category" class="rc__tags">
        <span class="rc__tag">{{ item.category ? $t(item.category) : '' }}</span>
      </div>
    </div>

    <!-- Bouton liste de courses -->
    <div class="rc__footer">
      <button class="rc__action-btn" @click="createShoppingList">
        <v-icon size="14">mdi-cart-plus</v-icon>
        Liste
      </button>
      <button
        class="rc__action-btn rc__action-btn--delete"
        @click="deleteRecipe"
        aria-label="Supprimer la recette"
      >
        <v-icon size="14">mdi-delete-outline</v-icon>
        Supprimer
      </button>
    </div>

    <v-snackbar v-model="snack.show" :timeout="2500">{{ snack.text }}</v-snackbar>
  </div>
</template>

<script setup>
import { ref, computed, watch } from "vue";
import { useRouter } from "vue-router";
import { useAuthStore } from "@/store/auth_store";
import { addShoppingList, getUserShoppingLists } from "@/service/shopping_list_service";
import { getIngredientsByBarcodes } from "@/service/ingredient_service";
import { getUserRecipeById } from "@/service/recipe_service";
import { getBaseRecipeById } from "@/service/base_recipe_service";

const props = defineProps({
  item: { type: Object, required: true },
});

const emit = defineEmits(["toggle-favorite", "delete"]);
const router = useRouter();
const authStore = useAuthStore();
const hovered = ref(false);
const snack = ref({ show: false, text: "" });
const validPreview = ref(true);
const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg';

const sourceKey = computed(() => props.item?.url || props.item?.image || props.item?.imageUrl || '');
const previewSrc = computed(() => validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage);

function onPreviewError() { validPreview.value = false; }
watch(sourceKey, (v) => { validPreview.value = !!v; });

function toggleFavorite() { emit("toggle-favorite", props.item); }
function openDetails() {
  router.push({ name: "recipe_detail", params: { id: props.item.id } });
}
function deleteRecipe() { emit("delete", props.item.id); }

async function createShoppingList() {
  if (!authStore.userid) {
    snack.value = { show: true, text: "Utilisateur non connecté." };
    return;
  }
  try {
    let r = await getUserRecipeById(authStore.userid, props.item.id);
    if (!r || r.baseRecipe === true) {
      const base = await getBaseRecipeById(props.item.id);
      if (base) r = base;
    }
    const ingredients = r?.ingredients || [];
    if (!ingredients.length) {
      snack.value = { show: true, text: "Aucun ingrédient à ajouter." };
      return;
    }
    const barcodes = ingredients.map((ing) => ing?.id).filter(Boolean);
    const fullInfos = barcodes.length ? await getIngredientsByBarcodes(authStore.userid, barcodes) : [];
    const items = ingredients.map((ing) => {
      const found = fullInfos.find((f) => f.id === ing?.id);
      const name = String(ing?.name || found?.productName || ing?.productName || ing?.id || "").trim();
      if (!name) return null;
      const grams = Number(ing.grams);
      const quantity = Number.isFinite(grams) && grams > 0 ? `${grams} g` : 1;
      return { name, quantity };
    }).filter(Boolean);
    if (!items.length) {
      snack.value = { show: true, text: "Aucun ingrédient valide." };
      return;
    }
    const listName = String(r?.title || props.item.title || "Liste de courses").trim();
    const existingLists = await getUserShoppingLists(authStore.userid);
    const alreadyGenerated = Object.values(existingLists || {}).some((list) => {
      if (!list) return false;
      return String(list.name || "").trim().toLowerCase() === listName.toLowerCase() && list.userGenerated === false;
    });
    if (alreadyGenerated) {
      snack.value = { show: true, text: "Cette liste existe déjà." };
      return;
    }
    await addShoppingList(authStore.userid, { name: listName, items, userGenerated: false });
    snack.value = { show: true, text: "Liste de courses créée." };
  } catch (e) {
    console.error(e);
    snack.value = { show: true, text: "Erreur lors de la création de la liste." };
  }
}
</script>

